      const dbPermissions = await db.query.permissions.findMany({
        where: eq(schema.permissions.role, user.role),
      });

      return {
        session,
        user,
        userPermissions: dbPermissions,
      };
    }),
  ],
  advanced: {
    database: {
      generateId: false,
    },
    cookiePrefix: "custom-prefix",
    crossSubDomainCookies: {
      enabled: false,
    },
  },
});


