						android: config.EXPO_PUBLIC_NATIVE_APP_URL,
						web: config.EXPO_PUBLIC_NATIVE_WEB_URL,
					}),
				});

				if (error) {
					onLoadingChange?.(false);
					toast.error(
						error.message ||
							t(`auth.${mode}.form.submit-button.unexpected-error`),
					);
					return;
				}
				toast.success("Our verification email has been sent to your inbox.");
				onLoadingChange?.(false);
				break;
			}
			case "phone": {
				const phoneData = data as { type: "phone"; phone: string };
				if (
					!(
						z.e164().safeParse(`+63${phoneData.phone}`).success &&
						isValidPhoneNumber(`+63${phoneData.phone}`) &&
						isPossiblePhoneNumber(`+63${phoneData.phone}`)
					)
				) {
					onLoadingChange?.(false);
					setError("phone", { message: "Invalid phone number" });
					return;
				}

				const { error } = await authClient.phoneNumber.sendOtp({
					phoneNumber: `+63${phoneData.phone}`,
				});

				if (error) {
					onLoadingChange?.(false);
					toast.error(
						error.message ||
							t(`auth.${mode}.form.submit-button.unexpected-error`),
					);
					return;
				}

				onLoadingChange?.(false);
				router.push("/(auth)/verify-otp");

				break;
			}
			default: {
